# Fail closed: verify every expected source fragment occurs exactly once before writing.
for old, new in changes:
    count = source.count(old)
    if count != 1:
        raise SystemExit(f'DỪNG AN TOÀN: Đoạn cần vá xuất hiện {count} lần (cần đúng 1). Không ghi file. Đoạn đầu: {old[:100]!r}')
updated = source
for old, new in changes:
    updated = updated.replace(old, new, 1)
TARGET.write_text(updated, encoding='utf-8')
print(f'Đã áp dụng {len(changes)} thay đổi có kiểm tra vào {TARGET}.')
